for rel, (expected, encoded) in FILES.items():
    target = Path.cwd() / rel
    data = zlib.decompress(base64.b64decode(encoded))
    if hashlib.sha256(data).hexdigest() != expected:
        raise SystemExit(f"embedded checksum failed: {rel}")
    target.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=target.parent, delete=False) as tmp:
        tmp.write(data)
        temp = Path(tmp.name)
    temp.replace(target)
    actual = hashlib.sha256(target.read_bytes()).hexdigest()
    if actual != expected:
        raise SystemExit(f"written checksum failed: {rel}")
    print(f"V5.2 full replacement verified: {rel} {actual}")
